        saAccessExceptionHint: { ps: "\u06A9\u0647 \u063A\u06CC\u0631\u0641\u0639\u0627\u0644\u0647 \u06CC\u0627 \u067E\u0627\u06CC \u062A\u0647 \u0631\u0633\u06D0\u062F\u0644\u06D0 \u0648\u064A \u0647\u0645\u060C \u0648\u0644\u0633\u0648\u0627\u0644\u06CD \u062A\u0647 \u0627\u062C\u0627\u0632\u0647 \u0648\u0631\u06A9\u0693\u0626", dr: "\u062D\u062A\u06CC \u0627\u06AF\u0631 \u063A\u06CC\u0631\u0641\u0639\u0627\u0644 \u06CC\u0627 \u0645\u0646\u0642\u0636\u06CC \u0628\u0627\u0634\u062F\u060C \u0628\u0647 \u0648\u0644\u0633\u0648\u0627\u0644\u06CC \u0627\u062C\u0627\u0632\u0647 \u062F\u0647\u06CC\u062F" },
