    const dist = (d) => [d.province_name, d.district_name, money(d.annual_fee), d.subscription_start ? `${formatDate(d.subscription_start)} \u2192 ${formatDate(d.subscription_end)}` : "\u2014", t(DIST_LABEL[d.effective_status])];
